<template><section class="module-page module-composed-page"><header class="module-heading"><div><h1>资源中心</h1><p>查看课程资源并发送到自己的实训环境，不支持下载到电脑。</p></div><el-button icon="el-icon-monitor" @click="$router.push('/training-environment')">选择实训环境</el-button></header><div class="course-filters"><el-input v-model="keyword" prefix-icon="el-icon-search" clearable placeholder="按资源名称搜索" /><el-select v-model="type" clearable placeholder="资源类型"><el-option v-for="item in types" :key="item" :label="item" :value="item" /></el-select></div><div class="module-table-wrap"><el-table :data="filtered" empty-text="暂无可用资源"><el-table-column prop="name" label="资源名称" min-width="220" /><el-table-column prop="resourceType" label="类型" width="110" /><el-table-column prop="courseName" label="所属课程" min-width="180" /><el-table-column label="操作" width="160" align="right"><template slot-scope="s"><el-button size="small" icon="el-icon-monitor" @click="$router.push({ path: '/training-environment', query: { courseId: s.row.courseId } })">发送到实训</el-button></template></el-table-column></el-table></div></section></template>
<script>
import { listUserCourses } from '@/api/Courses'
export default { data:()=>({rows:[],keyword:'',type:''}), computed:{types(){return [...new Set(this.rows.map(r=>r.resourceType))]},filtered(){return this.rows.filter(r=>(!this.keyword||r.name.includes(this.keyword))&&(!this.type||r.resourceType===this.type))}}, async created(){const r=await listUserCourses();this.rows=(r.data||[]).reduce((all,item)=>all.concat((item.resources||[]).map(resource=>Object.assign({},resource,{courseName:item.course.name,courseId:item.course.courseId}))),[])} }
</script>
